<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useRouter } from 'vue-router'
import PageHead from '@/components/PageHead.vue'
import CoomiIcon from '@/components/CoomiIcon.vue'
import { apiGet, apiSend } from '@/bridge/http'
import { useConfigStore } from '@/stores/config'
import { goBack } from '@/bridge/navigation'

interface Role { id:string; name:string; modelSelector?:string; prompt?:string; color?:string; icon?:string }
interface ProviderOption { id:string; name:string; models?:string[] }
interface Task { id:string; title:string; objective:string; status:string; mode:string; agents?:Array<{id:string;name:string;status:string}>; updatedAtMs:number; summary?:string }
const router=useRouter(); const route=useRoute(); const config=useConfigStore(); const tasks=ref<Task[]>([]); const providers=ref<ProviderOption[]>([]); const loading=ref(false); const error=ref(''); const showCreate=ref(route.name==='collab-new'); const objective=ref(''); const cwd=ref('/workspace'); const creating=ref(false)
const mode=ref<'parallel'|'coordinated'|'orchestrated'>('parallel'); const attachments=ref<string[]>([]); const roles=ref<Role[]>([{id:'executor',name:'执行者',prompt:'负责实现与改码，产出可验证结果。',modelSelector:''},{id:'reviewer',name:'审查者',prompt:'只读审查，指出问题与建议。',modelSelector:''}])
function importFiles(){window.CoomiAndroid?.importFiles?.()}
function onFilesImported(event:Event){const paths=(event as CustomEvent<{paths?:string[]}>).detail?.paths??[];attachments.value=Array.from(new Set([...attachments.value,...paths]))}
function removeAttachment(path:string){attachments.value=attachments.value.filter(item=>item!==path)}
  function statusText(s:string){return ({draft:'草稿',starting:'启动中',running:'执行中',completed:'已完成',failed:'失败',cancelled:'已取消',interrupted:'已中断'} as Record<string,string>)[s]||s}
async function load(){loading.value=true;try{await config.fetchProviders();const d=await apiGet<{tasks:Task[]}>('/api/collab/tasks');tasks.value=d.tasks??[];providers.value=config.providers.map(p=>({id:p.id,name:p.name,models:p.models}))}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}
async function create(){if(!objective.value.trim()||creating.value)return;creating.value=true;error.value='';try{const d=await apiSend<{taskId:string}>('/api/collab/tasks','POST',{task:objective.value.trim(),title:objective.value.trim().slice(0,42),cwd:cwd.value,auto_start:true,settings:{mode:mode.value,roles:roles.value},attachments:attachments.value});showCreate.value=false;objective.value='';if(d.taskId)router.push(`/collab/${d.taskId}`);await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{creating.value=false}}
onMounted(()=>{window.addEventListener('coomi:files-imported',onFilesImported);void load()});onBeforeUnmount(()=>window.removeEventListener('coomi:files-imported',onFilesImported))
</script>
<template><div class="page"><PageHead title="协同工作台" @back="goBack(router,'dashboard')"><template #right><button class="icon-btn blue" aria-label="创建协同任务" @click="showCreate=true"><CoomiIcon name="plus"/></button></template></PageHead><main class="body"><p v-if="error" class="notice err"><CoomiIcon name="alert" :size="14"/>{{error}}</p><p v-if="loading" class="hint">正在同步任务…</p><div v-else-if="!tasks.length" class="empty"><div class="empty-art"><CoomiIcon name="subtask" :size="30"/></div><b>还没有协同任务</b><span>定义目标，组建角色，让多个 AI 并行拆解并交付结果。</span><button class="btn primary" @click="showCreate=true">创建协同任务</button></div><div v-else class="cards"><button v-for="t in tasks" :key="t.id" class="card" @click="router.push(`/collab/${t.id}`)"><div class="card-head"><span class="tile"><CoomiIcon name="subtask" :size="18"/></span><span class="title">{{t.title}}</span><em :class="['status',t.status]">{{statusText(t.status)}}</em></div><p>{{t.objective}}</p><div class="foot"><span>{{t.mode==='parallel'?'并行执行':t.mode==='coordinated'?'协调执行':'集中调度'}}</span><span>{{t.agents?.length??0}} 个角色</span></div></button></div></main><div v-if="showCreate" class="mask" @click.self="showCreate=false"><section class="sheet"><div class="grip"/><h3>创建协同任务</h3><label>任务目标<textarea v-model="objective" rows="4" placeholder="例如：重构设置页面并完成验证"/></label><label>工作目录<input v-model="cwd" placeholder="/workspace"/></label><label>执行模式<select v-model="mode" class="mode-select"><option value="parallel">并行执行 · 同一快照独立交付</option><option value="coordinated">协调执行 · 顺序交接补充</option><option value="orchestrated">集中调度 · 规划后分工</option></select></label><p class="mode-help">{{mode==='parallel'?'适合互不依赖的独立方案。':mode==='coordinated'?'后一个成员会读取前一个成员的交接结果。':'首位成员先规划，其他成员依据计划执行。'}}</p><p class="role-title">执行角色</p><div v-for="r in roles" :key="r.id" class="role"><span class="role-icon"><CoomiIcon :name="r.icon||'user'" :size="16"/></span><span class="role-name">{{r.name}}</span><select v-model="r.modelSelector" aria-label="成员模型"><option value="">跟随默认模型</option><optgroup v-for="p in providers" :key="p.id" :label="p.name"><option v-for="m in p.models" :key="p.id+':'+m" :value="p.id+':'+m">{{m}}</option></optgroup></select><small>{{r.prompt}}</small></div><label>附件文件<button type="button" class="file-pick" @click="importFiles"><CoomiIcon name="fileRead" :size="15"/>从手机选择文件</button></label><div v-if="attachments.length" class="attachments"><button v-for="path in attachments" :key="path" type="button" @click="removeAttachment(path)"><span>{{path.split('/').pop()}}</span><CoomiIcon name="close" :size="12"/></button></div><div class="actions"><button class="btn" @click="showCreate=false">取消</button><button class="btn primary" :disabled="creating||!objective.trim()" @click="create">{{creating?'启动中…':'启动任务'}}</button></div></section></div></div></template>
<style scoped>.page{display:flex;flex-direction:column;height:100%;background:var(--page)}.body{flex:1;overflow:auto;padding:14px 12px calc(var(--safe-bottom)+24px)}.icon-btn{display:grid;place-items:center;width:40px;height:40px;border:0;border-radius:50%;background:none;color:var(--text-2)}.icon-btn.blue{color:var(--blue)}.notice{display:flex;gap:7px;align-items:center;padding:9px 11px;border-radius:var(--r-md);background:var(--danger-soft);color:var(--danger);font-size:12px}.hint{text-align:center;color:var(--text-3);font-size:13px}.empty{display:flex;flex-direction:column;align-items:center;gap:9px;padding:42px 20px;text-align:center;color:var(--text-3)}.empty b{color:var(--text);font-size:16px}.empty span{font-size:12.5px;line-height:1.7}.empty-art,.tile,.role-icon{display:grid;place-items:center;border-radius:11px;background:var(--blue-soft);color:var(--blue)}.empty-art{width:58px;height:58px;margin-bottom:4px}.btn{min-height:40px;padding:0 15px;border:0;border-radius:var(--r-md);background:var(--fill-strong);color:var(--text-2);font-size:13px;font-weight:600}.btn.primary{background:var(--blue);color:#fff}.cards{display:grid;gap:10px}.card{display:block;width:100%;padding:13px;border:1px solid var(--border);border-radius:var(--r-card);background:var(--bg-elev);color:var(--text);text-align:left}.card:active{background:var(--fill)}.card-head{display:flex;align-items:center;gap:9px}.tile{width:34px;height:34px;flex:none}.title{flex:1;min-width:0;font-size:14.5px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.status{font-style:normal;padding:3px 8px;border-radius:var(--r-pill);background:var(--fill);color:var(--text-3);font-size:10.5px}.status.running,.status.starting{background:var(--blue-soft);color:var(--blue)}.status.completed{background:var(--ok-soft);color:var(--ok)}.status.failed{background:var(--danger-soft);color:var(--danger)}.card p{margin:10px 0 8px;color:var(--text-2);font-size:12.5px;line-height:1.6;white-space:pre-wrap}.foot{display:flex;gap:12px;color:var(--text-3);font-size:11.5px}.mask{position:fixed;inset:0;z-index:70;display:flex;align-items:flex-end;background:rgba(0,0,0,.38)}.sheet{width:100%;max-height:82vh;overflow:auto;padding:8px 15px calc(var(--safe-bottom)+16px);border-radius:20px 20px 0 0;background:var(--bg);box-shadow:var(--shadow-sheet)}.grip{width:38px;height:4px;margin:3px auto 15px;border-radius:2px;background:var(--border-strong)}h3{margin:0 0 15px;font-size:17px}label{display:block;margin:11px 0;color:var(--text-2);font-size:12px}textarea,input{display:block;width:100%;margin-top:5px;padding:10px;border:1px solid var(--border);border-radius:var(--r-md);background:var(--fill);color:var(--text);font:inherit;font-size:13px;outline:none}.mode-select{width:100%;min-height:44px;margin-top:5px;border:1px solid var(--border);border-radius:var(--r-md);background:var(--fill);color:var(--text);padding:0 10px}.mode-help{margin:-4px 0 10px;color:var(--text-3);font-size:11px;line-height:1.55}.role-title{margin:15px 0 7px;color:var(--text-3);font-size:12px}.role{display:flex;align-items:center;gap:8px;min-height:42px;padding:7px 9px;border-radius:var(--r-md);background:var(--fill);font-size:13px}.role-icon{width:28px;height:28px}.role small{margin-left:auto;color:var(--text-3);font-size:10.5px}.role{flex-wrap:wrap}.role-name{font-weight:650}.role select{min-width:145px;max-width:52%;margin-left:auto;height:34px;border:1px solid var(--border);border-radius:var(--r-sm);background:var(--bg);color:var(--text);font-size:11px}.role small{flex-basis:100%;margin-left:36px}.file-pick{display:flex;align-items:center;justify-content:center;gap:6px;width:100%;min-height:44px;margin-top:6px;border:1px dashed var(--blue);border-radius:var(--r-md);background:var(--blue-soft);color:var(--blue);font-weight:600}.attachments{display:flex;flex-wrap:wrap;gap:6px}.attachments button{display:flex;align-items:center;gap:5px;max-width:100%;min-height:32px;padding:0 9px;border-radius:var(--r-pill);background:var(--fill);color:var(--text-2)}.attachments span{max-width:220px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{display:flex;gap:8px;margin-top:16px}.actions .btn{flex:1}</style>
